function primeiroProblema(pedido) {
  const itens = pedido.itens ?? []

  if (itens.length === 0) return 'pedido vazio'

  const endereco = (pedido.endereco ?? '').trim()
  if (endereco === '') return 'endereço ausente'

  // !(q > 0) pega ausente, zero, negativo e valor que não é número.
  if (itens.some((item) => !(item.quantidade > 0))) return 'quantidade inválida'

  if (pedido.total > 5000 && pedido.aprovado !== true) return 'precisa de aprovação'

  return null
}
